import { bech32Decode, parseArgs, pythonTupleRepr } from './lib/index.mjs';

export function main(argv = process.argv) {
  const parsed = parseArgs(argv);

  if (parsed.kind === 'help' || parsed.kind === 'error') {
    const stream = parsed.stream === 'stderr' ? process.stderr : process.stdout;
    stream.write(parsed.output);
    return parsed.code;
  }

  const result = bech32Decode(parsed.args.a);
  process.stdout.write(`${pythonTupleRepr(result)}\n`);
  return 0;
}

const exitCode = main();

if (exitCode !== 0) {
  process.exitCode = exitCode;
}

function getProgramName(argv) {
  const scriptPath = argv[1] ?? 'test2.mjs';
  const normalized = scriptPath.replace(/\\/g, '/');
  const segments = normalized.split('/');
  return segments[segments.length - 1] || 'test2.mjs';
}

function isNegativeNumberToken(token) {
  return /^-\d+(\.\d*)?([eE][+-]?\d+)?$/.test(token) || /^-\.\d+([eE][+-]?\d+)?$/.test(token);
}

function isOptionLikeToken(token) {
  return token.startsWith('-') && token !== '-' && !isNegativeNumberToken(token);
}

function isHelpToken(token) {
  return token === '-h' || token === '--help';
}

export function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A\n`;
}

export function buildHelp(programName) {
  return `${buildUsage(programName)}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

export function buildError(programName, message) {
  return `${buildUsage(programName)}${programName}: error: ${message}\n`;
}

export function parseArgs(argv) {
  const programName = getProgramName(argv);
  let a;
  const extras = [];

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--a') {
      const next = argv[index + 1];

      if (next === undefined || next === '--' || isOptionLikeToken(next)) {
        return {
          kind: 'error',
          code: 2,
          stream: 'stderr',
          output: buildError(programName, 'argument --a: expected one argument'),
        };
      }

      a = next;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      a = token.slice(4);
      continue;
    }

    if (isHelpToken(token)) {
      return {
        kind: 'help',
        code: 0,
        stream: 'stdout',
        output: buildHelp(programName),
      };
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    extras.push(token);
  }

  if (a === undefined) {
    return {
      kind: 'error',
      code: 2,
      stream: 'stderr',
      output: buildError(programName, 'the following arguments are required: --a'),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      code: 2,
      stream: 'stderr',
      output: buildError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    code: 0,
    args: { a },
  };
}

import { bech32CharsetIndex } from './charset.mjs';
import { bech32VerifyChecksum } from './checksum.mjs';

function hasPrintableAsciiOnly(value) {
  for (let index = 0; index < value.length; index += 1) {
    const code = value.codePointAt(index);

    if (code < 33 || code > 126) {
      return false;
    }
  }

  return true;
}

function hasMixedCase(value) {
  return value.toLowerCase() !== value && value.toUpperCase() !== value;
}

export function bech32Decode(value) {
  if (!hasPrintableAsciiOnly(value) || hasMixedCase(value)) {
    return [null, null];
  }

  const normalized = value.toLowerCase();
  const separatorIndex = normalized.lastIndexOf('1');

  if (
    separatorIndex < 1 ||
    separatorIndex + 7 > normalized.length ||
    normalized.length > 90
  ) {
    return [null, null];
  }

  const hrp = normalized.slice(0, separatorIndex);
  const data = [];

  for (const character of normalized.slice(separatorIndex + 1)) {
    const decoded = bech32CharsetIndex(character);

    if (decoded === -1) {
      return [null, null];
    }

    data.push(decoded);
  }

  if (!bech32VerifyChecksum(hrp, data)) {
    return [null, null];
  }

  return [hrp, data.slice(0, -6)];
}

function padHex(value, width) {
  return value.toString(16).padStart(width, '0');
}

function pythonStringRepr(value) {
  let result = '\'';

  for (const character of value) {
    const code = character.codePointAt(0);

    if (character === '\\') {
      result += '\\\\';
      continue;
    }

    if (character === '\'') {
      result += '\\\'';
      continue;
    }

    if (character === '\n') {
      result += '\\n';
      continue;
    }

    if (character === '\r') {
      result += '\\r';
      continue;
    }

    if (character === '\t') {
      result += '\\t';
      continue;
    }

    if (code >= 32 && code <= 126) {
      result += character;
      continue;
    }

    if (code <= 0xff) {
      result += `\\x${padHex(code, 2)}`;
      continue;
    }

    result += `\\u${padHex(code, 4)}`;
  }

  result += '\'';
  return result;
}

export function pythonRepr(value) {
  if (value === null) {
    return 'None';
  }

  if (typeof value === 'string') {
    return pythonStringRepr(value);
  }

  if (typeof value === 'number') {
    return String(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => pythonRepr(item)).join(', ')}]`;
  }

  throw new TypeError('Unsupported value for pythonRepr');
}

export function pythonTupleRepr(values) {
  const body = values.map((value) => pythonRepr(value)).join(', ');
  return values.length === 1 ? `(${body},)` : `(${body})`;
}

